{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/kanban-board.json
    Work items in lanes. Each lane has a title, a count and its cards; a card has a title, an optional tag and the person it belongs to. Axes: card (simple, detail: tag and person), cols (2, 3), tone, density. Moving a card between lanes is a port contract.
    Props (p): id, title, lanes, cards, countLabel, card, cols, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lanes = ($p['lanes'] ?? null)}
{var $v_cards = ($p['cards'] ?? null)}
{var $v_countLabel = ($p['countLabel'] ?? null)}
{var $v_card = ($p['card'] ?? 'detail')}
{var $v_cols = ($p['cols'] ?? '3')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_12}
  {capture $c_11}
    {foreach ui_l($v_lanes) as $v_lane}
      {capture $c_10}
        {capture $c_3}
          {capture $c_1}
            {=ui_text(ui_get($v_lane, ['title']))}
          {/capture}
          {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => 'base', 'Weight' => 'bold'], 'children' => $c_1])|noescape}
          {capture $c_2}
            {=ui_text(ui_tpl($v_countLabel, [ui_len(ui_where($v_cards, 'lane', ui_get($v_lane, ['key'])))]))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs', 'Class' => 'text-muted-foreground'], 'children' => $c_2])|noescape}
        {/capture}
        {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '2', 'Align' => 'center', 'Justify' => 'between'], 'children' => $c_3])|noescape}
        {capture $c_9}
          {foreach ui_l(ui_where($v_cards, 'lane', ui_get($v_lane, ['key']))) as $v_c}
            {capture $c_8}
              {capture $c_4}
                {=ui_text(ui_get($v_c, ['title']))}
              {/capture}
              {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'semibold'], 'children' => $c_4])|noescape}
              {if ui_t(ui_eq($v_card, 'detail'))}
                {capture $c_7}
                  {capture $c_5}
                    {=ui_text(ui_get($v_c, ['tag']))}
                  {/capture}
                  {=ui_include('blocks/pill.latte', ['p' => ['tone' => 'blue', 'icon' => 'tag'], 'children' => $c_5])|noescape}
                  {capture $c_6}
                    {=ui_text(ui_get($v_c, ['who']))}
                  {/capture}
                  {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs', 'Class' => 'text-muted-foreground'], 'children' => $c_6])|noescape}
                {/capture}
                {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '2', 'Align' => 'center', 'Justify' => 'between', 'Class' => 'flex-wrap'], 'children' => $c_7])|noescape}
              {/if}
            {/capture}
            {=ui_include('ui/list/list-item.latte', ['p' => ['Class' => ui_s(ui_cnv(['flex flex-col rounded bg-card inset-ring inset-ring-border', (ui_t(ui_eq($v_density, 'compact')) ? 'gap-2 p-2' : 'gap-2 p-4')])), 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_8])|noescape}
          {/foreach}
        {/capture}
        {=ui_include('ui/list/list.latte', ['p' => ['Class' => 'm-0 flex list-none flex-col gap-2 p-0'], 'children' => $c_9])|noescape}
      {/capture}
      {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '4', 'Align' => 'stretch', 'Class' => 'rounded bg-muted p-4', 'Attrs' => ui_attrs(['data-testid', 'lane'])], 'children' => $c_10])|noescape}
    {/foreach}
  {/capture}
  {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => ui_s((ui_t(ui_eq($v_cols, '2')) ? '1-2' : '1-3')), 'Class' => 'items-start gap-4', 'Attrs' => ui_attrs(['data-testid', 'lanes'])], 'children' => $c_11])|noescape}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_12])|noescape}
